import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = r"""
#include <torch/extension.h>
#include <c10/util/Optional.h>

torch::Tensor conv_transpose3d_forward(torch::Tensor x, torch::Tensor weight, c10::optional<torch::Tensor> bias);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

namespace {

constexpr int TX = 8;
constexpr int TY = 8;
constexpr int TZ = 4;
constexpr int RX = 2;                   // register blocking: outputs per thread along x
constexpr int RY = 2;                   // register blocking: outputs per thread along y
constexpr int TILE_X = TX * RX;         // 16
constexpr int TILE_Y = TY * RY;         // 16
constexpr int CO = 24;
constexpr int K = 3;
constexpr int PAD_X = TILE_X + K - 1;   // 18 (logical tile extent)
constexpr int PAD_Y = TILE_Y + K - 1;   // 18
constexpr int PAD_Z = TZ + K - 1;       // 6
// Bank-conflict reduction: pad the physical shared-memory row stride from
// 18 to 24 floats. In the inner loop a warp reads an 8(tx) x 4(ty) tile of
// input values; with stride 24 the four rows land on bank offsets
// {0, 24, 16, 8} (24*ty mod 32), so all 32 lanes hit 32 distinct banks
// instead of suffering the 2-way conflicts caused by the old stride of 18.
constexpr int SH_STRIDE_X = 24;
constexpr int SH_IN_ELEMS = PAD_Z * PAD_Y * PAD_X;          // 1944 logical elements
constexpr int SH_IN_SIZE = PAD_Z * PAD_Y * SH_STRIDE_X;     // 2592 physical elements
constexpr int SH_W_SIZE = K * K * K * CO;           // 648

__global__ void conv_transpose3d_k3_s1_p0_g1_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int n, int cin,
    int din, int hin, int win,
    int dout, int hout, int wout,
    bool has_bias) {

    __shared__ float sh_in[2 * SH_IN_SIZE];
    __shared__ __align__(16) float sh_w[2 * SH_W_SIZE];

    const int tid = threadIdx.x;
    const int tx = tid & (TX - 1);
    const int ty = (tid / TX) & (TY - 1);
    const int tz = tid / (TX * TY);

    const int ztiles = (dout + TZ - 1) / TZ;
    const int b = blockIdx.z / ztiles;
    const int ztile = blockIdx.z - b * ztiles;

    const int ox = blockIdx.x * TILE_X;
    const int oy = blockIdx.y * TILE_Y;
    const int oz = ztile * TZ;
    const int gx0 = ox + tx;
    const int gx1 = ox + tx + TX;
    const int gy0 = oy + ty;
    const int gy1 = oy + ty + TY;
    const int gz = oz + tz;
    const bool valid00 = (gx0 < wout) && (gy0 < hout) && (gz < dout);
    const bool valid01 = (gx1 < wout) && (gy0 < hout) && (gz < dout);
    const bool valid10 = (gx0 < wout) && (gy1 < hout) && (gz < dout);
    const bool valid11 = (gx1 < wout) && (gy1 < hout) && (gz < dout);

    float acc00[CO];
    float acc01[CO];
    float acc10[CO];
    float acc11[CO];
    if (has_bias) {
        #pragma unroll
        for (int co = 0; co < CO; ++co) {
            const float bv = bias[co];
            acc00[co] = bv;
            acc01[co] = bv;
            acc10[co] = bv;
            acc11[co] = bv;
        }
    } else {
        #pragma unroll
        for (int co = 0; co < CO; ++co) {
            acc00[co] = 0.0f;
            acc01[co] = 0.0f;
            acc10[co] = 0.0f;
            acc11[co] = 0.0f;
        }
    }

    const int in_plane = hin * win;
    const int in_vol = din * in_plane;
    const int out_plane = hout * wout;
    const int out_vol = dout * out_plane;

    // Prologue: stage input channel 0 into shared-memory buffer 0
    for (int idx = tid; idx < SH_IN_ELEMS; idx += TX * TY * TZ) {
        const int pz = idx / (PAD_Y * PAD_X);
        const int rem = idx - pz * (PAD_Y * PAD_X);
        const int py = rem / PAD_X;
        const int px = rem - py * PAD_X;
        const int iz = oz - (K - 1) + pz;
        const int iy = oy - (K - 1) + py;
        const int ix = ox - (K - 1) + px;
        float v = 0.0f;
        if (iz >= 0 && iz < din && iy >= 0 && iy < hin && ix >= 0 && ix < win) {
            const int in_idx = b * cin * in_vol + iz * in_plane + iy * win + ix;
            v = __ldg(x + in_idx);
        }
        sh_in[(pz * PAD_Y + py) * SH_STRIDE_X + px] = v;
    }
    for (int idx = tid; idx < SH_W_SIZE; idx += TX * TY * TZ) {
        const int kk = idx / CO;
        const int co = idx - kk * CO;
        sh_w[idx] = __ldg(w + co * K * K * K + kk);
    }
    __syncthreads();
    // Double-buffered pipeline: prefetch the next input channel / weights
    // into the alternate shared-memory buffer while accumulating the current one.
    for (int ci = 0; ci < cin; ++ci) {
        const int buf = (ci & 1) * SH_IN_SIZE;
        const int wbuf = (ci & 1) * SH_W_SIZE;
        const int nbuf = ((ci + 1) & 1) * SH_IN_SIZE;
        const int nwbuf = ((ci + 1) & 1) * SH_W_SIZE;
        if (ci + 1 < cin) {
            const int nci = ci + 1;
            for (int idx = tid; idx < SH_IN_ELEMS; idx += TX * TY * TZ) {
                const int pz = idx / (PAD_Y * PAD_X);
                const int rem = idx - pz * (PAD_Y * PAD_X);
                const int py = rem / PAD_X;
                const int px = rem - py * PAD_X;
                const int iz = oz - (K - 1) + pz;
                const int iy = oy - (K - 1) + py;
                const int ix = ox - (K - 1) + px;
                float v = 0.0f;
                if (iz >= 0 && iz < din && iy >= 0 && iy < hin && ix >= 0 && ix < win) {
                    const int in_idx = (b * cin + nci) * in_vol + iz * in_plane + iy * win + ix;
                    v = __ldg(x + in_idx);
                }
                sh_in[nbuf + (pz * PAD_Y + py) * SH_STRIDE_X + px] = v;
            }
            const int ci_w_base = nci * CO * K * K * K;
            for (int idx = tid; idx < SH_W_SIZE; idx += TX * TY * TZ) {
                const int kk = idx / CO;
                const int co = idx - kk * CO;
                sh_w[nwbuf + idx] = __ldg(w + ci_w_base + co * K * K * K + kk);
            }
        }
        if (valid00 || valid01 || valid10 || valid11) {
            #pragma unroll
            for (int kz = 0; kz < K; ++kz) {
                const int pz = tz + (K - 1) - kz;
                #pragma unroll
                for (int ky = 0; ky < K; ++ky) {
                    const int py0 = ty + (K - 1) - ky;
                    const int py1 = py0 + TY;
                    #pragma unroll
                    for (int kx = 0; kx < K; ++kx) {
                        const int px = tx + (K - 1) - kx;
                        const int sbase0 = buf + (pz * PAD_Y + py0) * SH_STRIDE_X + px;
                        const int sbase1 = sbase0 + TY * SH_STRIDE_X;
                        const float v00 = sh_in[sbase0];
                        const float v01 = sh_in[sbase0 + TX];
                        const float v10 = sh_in[sbase1];
                        const float v11 = sh_in[sbase1 + TX];
                        const int kk = (kz * K + ky) * K + kx;
                        const int wbase = wbuf + kk * CO;
                        const float4* w4 = reinterpret_cast<const float4*>(sh_w + wbase);
                        #pragma unroll
                        for (int c4 = 0; c4 < CO / 4; ++c4) {
                            const float4 wv = w4[c4];
                            const int co = c4 * 4;
                            acc00[co + 0] = fmaf(v00, wv.x, acc00[co + 0]);
                            acc00[co + 1] = fmaf(v00, wv.y, acc00[co + 1]);
                            acc00[co + 2] = fmaf(v00, wv.z, acc00[co + 2]);
                            acc00[co + 3] = fmaf(v00, wv.w, acc00[co + 3]);
                            acc01[co + 0] = fmaf(v01, wv.x, acc01[co + 0]);
                            acc01[co + 1] = fmaf(v01, wv.y, acc01[co + 1]);
                            acc01[co + 2] = fmaf(v01, wv.z, acc01[co + 2]);
                            acc01[co + 3] = fmaf(v01, wv.w, acc01[co + 3]);
                            acc10[co + 0] = fmaf(v10, wv.x, acc10[co + 0]);
                            acc10[co + 1] = fmaf(v10, wv.y, acc10[co + 1]);
                            acc10[co + 2] = fmaf(v10, wv.z, acc10[co + 2]);
                            acc10[co + 3] = fmaf(v10, wv.w, acc10[co + 3]);
                            acc11[co + 0] = fmaf(v11, wv.x, acc11[co + 0]);
                            acc11[co + 1] = fmaf(v11, wv.y, acc11[co + 1]);
                            acc11[co + 2] = fmaf(v11, wv.z, acc11[co + 2]);
                            acc11[co + 3] = fmaf(v11, wv.w, acc11[co + 3]);
                        }
                    }
                }
            }
        }
        __syncthreads();
    }

    const int out_base0 = b * CO * out_vol + gz * out_plane + gy0 * wout;
    const int out_base1 = b * CO * out_vol + gz * out_plane + gy1 * wout;
    if (valid00) {
        #pragma unroll
        for (int co = 0; co < CO; ++co) {
            out[out_base0 + gx0 + co * out_vol] = acc00[co];
        }
    }
    if (valid01) {
        #pragma unroll
        for (int co = 0; co < CO; ++co) {
            out[out_base0 + gx1 + co * out_vol] = acc01[co];
        }
    }
    if (valid10) {
        #pragma unroll
        for (int co = 0; co < CO; ++co) {
            out[out_base1 + gx0 + co * out_vol] = acc10[co];
        }
    }
    if (valid11) {
        #pragma unroll
        for (int co = 0; co < CO; ++co) {
            out[out_base1 + gx1 + co * out_vol] = acc11[co];
        }
    }
}

}  // namespace

torch::Tensor conv_transpose3d_forward(torch::Tensor x, torch::Tensor weight, c10::optional<torch::Tensor> bias) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "x must be NCDHW");
    TORCH_CHECK(weight.dim() == 5, "weight must be (in_channels, out_channels, kD, kH, kW)");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");

    const int n = static_cast<int>(x.size(0));
    const int cin = static_cast<int>(x.size(1));
    const int din = static_cast<int>(x.size(2));
    const int hin = static_cast<int>(x.size(3));
    const int win = static_cast<int>(x.size(4));

    TORCH_CHECK(weight.size(0) == cin, "weight in_channels mismatch");
    TORCH_CHECK(weight.size(1) == CO, "this kernel expects out_channels == 24");
    TORCH_CHECK(weight.size(2) == K && weight.size(3) == K && weight.size(4) == K,
                "this kernel expects kernel_size == 3");

    const bool has_bias = bias.has_value() && bias->defined();
    if (has_bias) {
        TORCH_CHECK(bias->is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias->scalar_type() == torch::kFloat32, "bias must be float32");
        TORCH_CHECK(bias->is_contiguous(), "bias must be contiguous");
        TORCH_CHECK(bias->numel() == CO, "bias must have out_channels elements");
    }

    const int dout = din + K - 1;
    const int hout = hin + K - 1;
    const int wout = win + K - 1;

    auto out = torch::empty({n, CO, dout, hout, wout}, x.options());

    const dim3 block(TX * TY * TZ);
    const dim3 grid(
        (wout + TILE_X - 1) / TILE_X,
        (hout + TILE_Y - 1) / TILE_Y,
        n * ((dout + TZ - 1) / TZ));

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    conv_transpose3d_k3_s1_p0_g1_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias->data_ptr<float>() : nullptr,
        out.data_ptr<float>(),
        n, cin,
        din, hin, win,
        dout, hout, wout,
        has_bias);

    return out;
}
"""

_mod = load_inline(
    name="custom_conv_transpose3d_k3",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(in_channels, out_channels, (kernel_size, kernel_size, kernel_size),
                                                   stride=stride, padding=padding, output_padding=output_padding,
                                                   dilation=dilation, groups=groups, bias=bias)

        if self.conv_transpose3d.stride != (1, 1, 1):
            raise NotImplementedError("ModelNew custom kernel supports stride == 1 only")
        if self.conv_transpose3d.padding != (0, 0, 0):
            raise NotImplementedError("ModelNew custom kernel supports padding == 0 only")
        if self.conv_transpose3d.output_padding != (0, 0, 0):
            raise NotImplementedError("ModelNew custom kernel supports output_padding == 0 only")
        if self.conv_transpose3d.dilation != (1, 1, 1):
            raise NotImplementedError("ModelNew custom kernel supports dilation == 1 only")
        if self.conv_transpose3d.groups != 1:
            raise NotImplementedError("ModelNew custom kernel supports groups == 1 only")
        if kernel_size != 3 or out_channels != 24:
            raise NotImplementedError("ModelNew custom kernel is specialized for kernel_size == 3 and out_channels == 24")

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _mod.conv_transpose3d_forward(
            x.contiguous(),
            self.conv_transpose3d.weight.contiguous(),
            self.conv_transpose3d.bias,
        )

